  "implementation": "def solve(case):
    import collections
    if not all(k in case for k in ("edges","communities","resolution")):
        raise ValueError("Missing required fields")
    edges = case["edges"]
    communities = dict(case["communities"])
    resolution = case["resolution"]
    adj = {}
    deg = {}
    total_weight = 0.0
    for u, v, w in edges:
        total_weight += w
        adj.setdefault(u, {})[v] = adj.get(u, {}).get(v, 0) + w
        adj.setdefault(v, {})[u] = adj.get(v, {}).get(u, 0) + w
        deg[u] = deg.get(u, 0) + w
        deg[v] = deg.get(v, 0) + w
    for node in communities:
        deg.setdefault(node, 0)
    comm_tot = collections.defaultdict(float)
    for node, comm in communities.items():
        comm_tot[comm] += deg[node]
    nodes = sorted(communities.keys())
    moves = []
    if total_weight == 0:
        return {"communities": communities, "moves": moves}
    inv2m = 1.0 / (2.0 * total_weight)
    inv4m2 = 1.0 / ((2.0 * total_weight) ** 2)
    for node in nodes:
        cur_comm = communities[node]
        nbr_comm_w = collections.defaultdict(float)
        if node in adj:
            for nbr, w in adj[node].items():
                nc = communities.get(nbr)
                if nc is not None:
                    nbr_comm_w[nc] += w
        candidates = set(nbr_comm_w.keys()) | {cur_comm}
        best_gain = 0.0
        best_comm = cur_comm
        k_i_cur = nbr_comm_w.get(cur_comm, 0.0)
        k_i = deg[node]
        tot_cur = comm_tot[cur_comm]
        for cand_comm in candidates:
            k_i_B = nbr_comm_w.get(cand_comm, 0.0)
            tot_B = comm_tot[cand_comm]
            delta = (2 * k_i_B - 2 * k_i_cur) * inv2m - resolution * inv4m2 * (
                (tot_B + k_i) ** 2 - tot_B ** 2 - (tot_cur - k_i) ** 2 + tot_cur ** 2
            )
            if delta > best_gain + 1e-12:
                best_gain = delta
                best_comm = cand_comm
            elif abs(delta - best_gain) <= 1e-12 and cand_comm < best_comm:
                best_gain = delta
                best_comm = cand_comm
        if best_comm != cur_comm and best_gain > 1e-12:
            moves.append({"from": cur_comm, "node": node, "to": best_comm})
            comm_tot[cur_comm] -= k_i
            comm_tot[best_comm] += k_i
            communities[node] = best_comm
    return {"communities": communities, "moves": moves}
